165|/* One option cell: what we resolved it to, and what the sheet said if that
166|   differs. A value we couldn't place is shown as typed and underlined, never
167|   blanked — the whole point is that the row still reaches the person.
168|
169|   When the matched drink turns out not to offer it, the cell also carries the
170|   ways out: this drink's own options, one click each. */
171|function optionCell(row, axis, resolved, raw) {
172|  const cell = el('td');
173|  const typed = (raw || '').trim();
174|  const problems = ((row.match && row.match.unmapped) || []).filter((u) => u.axis === axis);
175|  // Asked for, and this drink simply hasn't got that axis — a slush has no ice
176|  // level. Nothing to pick, so say plainly that it isn't going in the order.
177|  const gone = ((row.match && row.match.dropped) || []).find((d) => d.axis === axis);
178|  if (gone) {
179|    const cell = el('td');
180|    cell.append(el('span', 'dropped', gone.asked));
181|    cell.append(el('span', 'was', 'not sent'));
182|    return cell;
183|  }
184|  // A row can ask for four toppings and only trip on the third, so the ones
185|  // that fitted stay shown as normal and only the odd one out gets a fixer.
186|  const kept = axis === 'toppings'
187|    ? ((row.canonical && row.canonical.toppings) || [])
188|        .filter((name) => !problems.some((p) => p.asked === name)).join(', ')
189|    : (problems.length ? '' : resolved);
190|
191|  if (kept) {
192|    cell.append(document.createTextNode(kept));
193|    if (typed && typed.toLowerCase() !== kept.toLowerCase()) {
194|      cell.append(el('span', 'was', typed));
195|    }
196|  } else if (problems.length) {
197|    cell.append(el('span', 'unresolved', problems.map((p) => p.asked).join(', ')));
198|  } else if (typed) {
199|    cell.append(el('span', 'unresolved', typed));
200|  } else {
201|    cell.append(el('span', 'default-value', '—'));
202|  }
203|  problems.forEach((problem) => cell.append(optionFixer(row, axis, problem)));
204|  return cell;
205|}
