207|/* Send one row's correction and redraw from whatever comes back.
208|
209|   Redrawing the whole page rather than patching the cell is deliberate: one
210|   change moves the price, the totals, the row's notes and sometimes a
211|   sheet-level warning, and the server has already worked all of that out. */
212|function saveRow(rowNumber, changes, feedback, focusAfter) {
213|  if (feedback) feedback.textContent = 'Saving…';
214|  pendingSaves += 1;
215|  const save = async () => {
216|    focusKey = focusAfter || null;
217|    lastSaveError = null;
218|    try {
219|      const response = await fetch(`/api/runs/${runId}/rows/${rowNumber}`, {
220|        method: 'POST',
221|        headers: { 'Content-Type': 'application/json' },
222|        body: JSON.stringify(changes),
223|      });
224|      const data = await response.json();
225|      if (!data.ok) throw new Error(data.error || 'that didn\'t save');
226|      render(data.run, data.stages);
227|    } catch (error) {
228|      lastSaveError = error;
229|      if (feedback) feedback.textContent = error.message;
230|      else window.alert(error.message);
231|    } finally {
232|      pendingSaves -= 1;
233|    }
234|  };
235|  saveBarrier = saveBarrier.then(save, save);
236|  return saveBarrier;
237|}
238|
239|const setDrink = (rowNumber, drink, feedback) =>
240|  drink ? saveRow(rowNumber, { drink }, feedback) : undefined;
241|
242|/* What to send for one axis when somebody picks a replacement. Toppings are a
243|   list, so the pick swaps out the one entry that didn't fit and leaves the rest
244|   of the order alone; "" drops it and takes the store's default. */
245|function changeFor(row, axis, asked, picked) {
246|  if (axis !== 'toppings') return { [axis]: picked };
247|  const current = (row.canonical && row.canonical.toppings) || row.toppings || [];
248|  const next = current
249|    .map((name) => (name === asked ? picked : name))
250|    .filter(Boolean);
251|  return { toppings: next };
252|}
