254|/* The fix-it control for a modifier this drink can't do: what it can do
255|   instead, plus the option of going without. Never applied on its own. */
256|function optionFixer(row, axis, problem) {
257|  const wrap = el('div', 'fixer');
258|  const feedback = el('div', 'why');
259|  const choices = ((row.match && row.match.choices) || {})[axis] || [];
260|  const line = el('div', 'suggest-line');
261|
262|  const pick = (value) => saveRow(
263|    row.row_number, changeFor(row, axis, problem.asked, value), feedback);
264|
265|  if (problem.asked) line.append(el('span', 'why', `${problem.asked} →`));
266|  if (choices.length > 6) {
267|    // 21 toppings is a menu, not a row of buttons.
268|    const select = el('select', 'drink-input');
269|    select.setAttribute('aria-label', `Choose the ${axis} for row ${row.row_number}`);
270|    const blank = document.createElement('option');
271|    blank.value = '';
272|    blank.textContent = 'pick one…';
273|    select.append(blank);
274|    choices.forEach((name) => {
275|      const option = document.createElement('option');
276|      option.value = name;
277|      option.textContent = name;
278|      select.append(option);
279|    });
280|    select.addEventListener('change', () => { if (select.value) pick(select.value); });
281|    line.append(select);
282|  } else {
283|    choices.forEach((name) => {
284|      const button = el('button', 'chip', name);
285|      button.type = 'button';
286|      button.addEventListener('click', () => pick(name));
287|      line.append(button);
288|    });
289|  }
290|
291|  const drop = el('button', 'chip apply', choices.length ? 'Leave it out' : 'Clear');
292|  drop.type = 'button';
293|  drop.addEventListener('click', () => pick(''));
294|  line.append(drop);
295|
296|  wrap.append(line, feedback);
297|  return wrap;
298|}
299|
300|/* A text box with a typeahead list behind it. Two sources, one control: the
301|   drink list is 149 names and is searched on the server, where the ranking
302|   knows that "ta" should reach Taro Slush; a drink's own topping list is twenty
303|   names and already in the run, so the browser filters it. */
304|function searchBox({ key, value, placeholder, label, list, action, onPick }) {
305|  const wrap = el('div', 'suggest-line');
306|  // Named but never re-focused after a save. These commit on blur or Enter, so
307|  // by the time one saves the user has moved on — and putting the caret back
308|  // would both fight the Tab that got them out and pop the list open again.
309|  const input = mark(el('input', 'drink-input'), key);
310|  const datalist = el('datalist');
311|  datalist.id = `list-${key}`;
312|  input.setAttribute('list', datalist.id);
313|  input.setAttribute('placeholder', placeholder || '');
314|  input.setAttribute('aria-label', label);
315|  input.setAttribute('autocomplete', 'off');
316|  if (value) input.value = value;
317|
318|  const fill = (names) => {
319|    datalist.textContent = '';
320|    (names || []).forEach((name) => {
321|      const option = document.createElement('option');
322|      option.value = name;
323|      datalist.append(option);
324|    });
325|  };
326|
327|  if (list) {
328|    fill(list);
329|  } else {
330|    // Debounced, and last-response-wins so a slow reply for "ta" can't
331|    // overwrite the results for "taro".
332|    let timer = null;
333|    let latest = 0;
334|    input.addEventListener('input', () => {
335|      const text = input.value.trim();
336|      window.clearTimeout(timer);
337|      if (!text) { fill([]); return; }
338|      timer = window.setTimeout(async () => {
339|        const mine = ++latest;
340|        try {
341|          const restaurantId = currentRun && currentRun.source
342|            ? currentRun.source.restaurant_id : '';
343|          const storeQuery = restaurantId
344|            ? `&restaurant_id=${encodeURIComponent(restaurantId)}` : '';
345|          const response = await fetch(
346|            `/api/drinks?q=${encodeURIComponent(text)}&limit=6${storeQuery}`);
347|          const data = await response.json();
348|          if (mine === latest) fill(data.drinks || []);
349|        } catch (error) {
350|          /* the box still takes a typed name; the search is a convenience */
351|        }
352|      }, 120);
353|    });
354|  }
355|
356|  // Commit on Enter, on picking from the list, and on leaving the box — but
357|  // only when the text actually changed, so tabbing through a table of these
358|  // doesn't fire a save per column.
359|  let sent = null;
360|  const submit = () => {
361|    const text = input.value.trim();
362|    if (text === (value || '') || text === sent) return;
363|    sent = text;
364|    onPick(text);
365|  };
366|  input.addEventListener('keydown', (event) => {
367|    if (event.key === 'Enter') { event.preventDefault(); submit(); }
368|  });
369|  input.addEventListener('change', submit);
370|
371|  wrap.append(input, datalist);
372|  if (action) {
373|    const button = el('button', 'chip apply', action);
374|    button.type = 'button';
375|    button.addEventListener('click', submit);
376|    wrap.append(button);
377|  }
378|  return wrap;
379|}
380|
381|/* The drink cell for a row we couldn't match: what they wrote, the near
382|   misses as one-click buttons, and the full menu behind a picker. Nothing is
383|   applied without someone choosing it. */
384|function drinkFixer(row) {
385|  const wrap = el('div', 'fixer');
386|  const feedback = el('div', 'why');
387|  const suggestions = (row.suggestions && row.suggestions.drink) || [];
388|
389|  if (suggestions.length) {
390|    const line = el('div', 'suggest-line');
391|    line.append(el('span', 'why', 'Did you mean'));
392|    suggestions.forEach((name) => {
393|      const button = el('button', 'chip', name);
394|      button.type = 'button';
395|      button.addEventListener('click', () => setDrink(row.row_number, name, feedback));
396|      line.append(button);
397|    });
398|    wrap.append(line);
399|  }
400|
401|  wrap.append(searchBox({
402|    key: `fix-drink-${row.row_number}`,
403|    placeholder: suggestions.length ? 'or search the menu…' : 'search the menu…',
404|    label: `Choose the drink for row ${row.row_number}`,
405|    action: 'Use this',
406|    onPick: (name) => setDrink(row.row_number, name, feedback),
407|  }), feedback);
408|  return wrap;
409|}
410|
411|/* --- review & edit -------------------------------------------------------- */
412|/* One block per order, not ten columns.
413|
414|   The read-only table is text and shares a line out happily. Controls don't:
415|   nine of them need roughly 1200px before a dropdown stops clipping its own
416|   value, and the page is 920px, so a table can only end in a sideways scroll.
417|   Stacking the fields costs vertical space, which is free, and buys every
418|   control a readable width at any window size.
419|
420|   What each control offers comes from the matched drink, because the store's
421|   vocabulary and one drink's vocabulary are very different things — a slush has
422|   no ice level at all. Until a row has a drink there is nothing to ask, so it
423|   falls back to the whole store's. */
424|
425|function axisChoices(row, run, axis) {
426|  const available = (row.match && row.match.available) || null;
427|  if (available && available[axis] && available[axis].length) return available[axis];
428|  if (available) return [];   // matched, and this drink genuinely hasn't got it
429|  return ((run.match && run.match.vocabulary) || {})[axis] || [];
430|}
431|
432|/* A labelled control. The label is a real <label> where there is a single
433|   control to point it at, so clicking the word focuses the thing under it. */
434|function field(labelText, control, options) {
435|  const box = el('div', 'field' + ((options && options.className) ? ' ' + options.className : ''));
436|  const label = el('label', 'field-label', labelText);
437|  if (options && options.id) {
438|    control.id = options.id;
439|    label.setAttribute('for', options.id);
440|  }
441|  box.append(label, control);
442|  return box;
443|}
444|
445|function selectField(row, run, axis, labelText, current) {
446|  const choices = axisChoices(row, run, axis);
447|  if (!choices.length) {
448|    const none = el('div', 'field-empty', 'not on this drink');
449|    return field(labelText, none, { className: 'field-off' });
450|  }
451|
452|  const key = `${row.row_number}-${axis}`;
453|  const select = mark(el('select', 'cell-input'), key);
454|  const blank = document.createElement('option');
455|  blank.value = '';
456|  blank.textContent = 'store default';
457|  select.append(blank);
458|
459|  let listed = false;
460|  choices.forEach((name) => {
461|    const option = document.createElement('option');
462|    option.value = name;
463|    option.textContent = name;
464|    if (name === current) { option.selected = true; listed = true; }
465|    select.append(option);
466|  });
467|  if (current && !listed) {
468|    // The sheet asked for something this drink hasn't got. Keep it selected and
469|    // named rather than snapping the dropdown to a value nobody chose.
470|    const option = document.createElement('option');
471|    option.value = current;
472|    option.textContent = `${current} — not on this drink`;
473|    option.selected = true;
474|    select.append(option);
475|  }
476|  // A dropdown can keep the focus: it is already where the user is looking,
477|  // and focusing a select doesn't make it drop open the way a typeahead does.
478|  select.addEventListener('change', () =>
479|    saveRow(row.row_number, { [axis]: select.value }, null, key));
480|  return field(labelText, select, { id: `row-${key}` });
481|}
482|
483|function toppingsField(row, run) {
484|  const holder = el('div', 'topping-field');
485|  const current = (row.canonical && row.canonical.toppings) || [];
486|  const counts = (row.canonical && row.canonical.topping_quantities) || {};
487|  // Send the count back along with the name, so editing one topping doesn't
488|  // quietly turn somebody's "2x pudding" into one pudding.
489|  const asText = (name) => (counts[name] > 1 ? `${counts[name]}x ${name}` : name);
490|  const save = (names) => saveRow(row.row_number, { toppings: names });
491|
492|  current.forEach((name) => {
493|    const chip = el('button', 'chip topping',
494|      counts[name] > 1 ? `${name} ×${counts[name]}` : name);
495|    chip.type = 'button';
496|    chip.setAttribute('aria-label', `Remove ${name} from row ${row.row_number}`);
497|    chip.append(el('span', 'remove', '✕'));
498|    chip.addEventListener('click', () =>
499|      save(current.filter((other) => other !== name).map(asText)));
500|    holder.append(chip);
